def remove_repeated_words(s):
    words = s.split()
    out = []
    for w in words:
        if not out or out[-1] != w:
            out.append(w)
    return ' '.join(out)

def transpose_list_of_dicts(records):
    if not records:
        return {}
    keys = records[0].keys()
    return {k: [r[k] for r in records] for k in keys}

