def is_valid_sudoku_column(col):
    if len(col) != 9:
        return False
    seen = set()
    for v in col:
        if not isinstance(v, int) or v < 0 or v > 9:
            return False
        if v != 0:
            if v in seen:
                return False
            seen.add(v)
    return True

