def is_valid_markdown_link(s):
    import re
    m = re.fullmatch(r'\[([^\]]+)\]\((\S+)\)', s)
    if not m:
        return False
    url = m.group(2)
    return url.startswith('http://') or url.startswith('https://')

def is_perfect_number(n):
