def add_months_to_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    total = (y * 12 + (m - 1)) + n_months
    ny = total // 12
    nm = total % 12 + 1
    dim = [31, 29 if is_leap(ny) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][nm - 1]
    nd = min(d, dim)
    return (ny, nm, nd)
